class Connection:
    def __init__(self,zone1:str,zone2:str,max_link_capacity:int=1)->None:
        self.zone1=zone1; self.zone2=zone2
        self.max_link_capacity=max_link_capacity

    def connects(self,zone_name:str)->bool:
        return zone_name==self.zone1 or zone_name==self.zone2

    def other_end(self,zone_name:str)->str:
        return self.zone2 if zone_name==self.zone1 else self.zone1

    def key(self)->str:
        return "-".join(sorted([self.zone1,self.zone2]))
```

