from zone import Zone
from connection import Connection
from typing import Optional

class Network:
    def __init__(self)->None:
        self.zones:dict[str,Zone]={}
        self.connections:list[Connection]=[]

    def add_zone(self,zone:Zone)->None:
        self.zones[zone.name]=zone

    def add_connection(self,conn:Connection)->None:
        self.connections.append(conn)

    def get_neighbors(self,zone_name:str)->list[tuple[str,Connection]]:
        result=[]
        for conn in self.connections:
            if conn.connects(zone_name):
                result.append((conn.other_end(zone_name),conn))
        return result

    def find_connection(self,a:str,b:str)->Optional[Connection]:
        for conn in self.connections:
            if conn.connects(a) and conn.connects(b):
                return conn
        return None
```

