```python
import heapq
from typing import Optional
from network import Network

class Pathfinder:
    def __init__(self,network:Network)->None:
        self.network=network

    def find_path(self,start:str,end:str)->Optional[list[str]]:
        if start not in self.network.zones or end not in self.network.zones:
            return None
        heap:list[tuple[float,str,list[str]]]=[(0.0,start,[start])]
        best_cost:dict[str,float]={}
        while heap:
            cost,current,path=heapq.heappop(heap)
            if current in best_cost:
                continue
            best_cost[current]=cost
            if current==end:
                return path
            for neighbor,_conn in self.network.get_neighbors(current):
                if neighbor in best_cost:
                    continue
                nz=self.network.zones[neighbor]
                if nz.is_blocked():
                    continue
                step=2.0 if nz.zone_type=="restricted" else \
                     0.9 if nz.zone_type=="priority" else 1.0
                heapq.heappush(heap,(cost+step,neighbor,path+[neighbor]))
        return None
```

**Why 0.9 for priority?** — Same turn cost as normal, but Dijkstra naturally prefers it when paths tie.
